    "\n"
    "# AppImage update mode is intentionally separate from the legacy three-file ZIP\n"
    "# updater. The AppImage is a single immutable executable, not a writable AppDir.\n"
    "APPIMAGE_ASSET = re.compile(r'^File-Sorter-v(\\d+)\\.(\\d+)\\.(\\d+)-x86_64\\.AppImage$')\n"
    "MAX_APPIMAGE_SIZE = 300 * 1024 * 1024\n"
    "\n"
    "\n"
    "def latest_appimage():\n"
    "    try:\n"
    "        with request(API) as response:\n"
    "            raw = response.read(1024 * 1024 + 1)\n"
    "        if len(raw) > 1024 * 1024:\n"
    "            raise UpdateError('GitHub release metadata too large.')\n"
    "        release = json.loads(raw)\n"
    "    except (ValueError, OSError, urllib.error.URLError) as exc:\n"
    "        raise UpdateError(f'Cannot read GitHub release metadata: {exc}') from exc\n"
    "    if not isinstance(release, dict) or release.get('draft') or release.get('prerelease'):\n"
    "        raise UpdateError('Latest GitHub release is not stable.')\n"
    "    tag = release.get('tag_name', '')\n"
    "    if not isinstance(tag, str) or not re.fullmatch(r'[\\w.-]{1,100}', tag, re.ASCII):\n"
    "        raise UpdateError('Invalid release tag.')\n"
    "    matches = []\n"
    "    for asset in release.get('assets', []):\n"
    "        if not isinstance(asset, dict):\n"
    "            continue\n"
    "        name = asset.get('name', '')\n"
    "        match = APPIMAGE_ASSET.fullmatch(name) if isinstance(name, str) else None\n"
    "        if match:\n"
    "            size = asset.get('size')\n"
    "            digest = asset.get('digest', '')\n"
    "            url = asset.get('browser_download_url', '')\n"
    "            if (not isinstance(size, int) or isinstance(size, bool) or\n"
    "                    not 1024 < size < MAX_APPIMAGE_SIZE or not isinstance(digest, str) or\n"
    "                    not re.fullmatch(r'sha256:[0-9a-fA-F]{64}', digest) or\n"
    "                    not isinstance(url, str) or not url.startswith(ASSET_PREFIX) or\n"
    "                    not url.endswith('/' + name)):\n"
    "                raise UpdateError(f'Invalid AppImage asset metadata: {name}')\n"
    "            matches.append((tuple(map(int, match.groups())), {\n"
    "                'name': name, 'size': size, 'digest': digest.partition(':')[2].lower(),\n"
    "                'url': url, 'tag': tag,\n"
    "            }))\n"
    "    if not matches:\n"
    "        return None\n"
    "    if len(matches) != 1:\n"
    "        raise UpdateError('Release contains multiple matching AppImages.')\n"
    "    return matches[0]\n"
    "\n"
    "\n"
    "def is_x64_appimage(file):\n"
    "    with open(file, 'rb') as source:\n"
    "        header = source.read(20)\n"
    "    return (len(header) == 20 and header[:4] == b'\\x7fELF' and\n"
    "            header[4:6] == b'\\x02\\x01' and header[8:11] == b'AI\\x02' and\n"
    "            header[18:20] == b'\\x3e\\x00')\n"
    "\n"
    "\n"
    "def install_appimage(dest, asset):\n"
    "    # Download to same directory, verify before replace, never touch settings.\n"
    "    if dest.is_symlink() or not dest.is_file() or not is_x64_appimage(dest):\n"
    "        raise UpdateError('Installed AppImage is not a safe x86-64 AppImage file.')\n"
    "    fd, name = tempfile.mkstemp(dir=dest.parent, prefix='.file-sorter-update-', suffix='.AppImage')\n"
    "    staged = Path(name)\n"
    "    try:\n"
    "        copied = 0\n"
    "        digest = hashlib.sha256()\n"
    "        with os.fdopen(fd, 'wb') as stream, request(asset['url']) as response:\n"
    "            while block := response.read(262144):\n"
    "                copied += len(block)\n"
    "                if copied > asset['size'] or copied > MAX_APPIMAGE_SIZE:\n"
    "                    raise UpdateError('AppImage exceeded expected download size.')\n"
    "                digest.update(block)\n"
    "                stream.write(block)\n"
    "            stream.flush()\n"
    "            os.fsync(stream.fileno())\n"
    "        if copied != asset['size'] or digest.hexdigest() != asset['digest']:\n"
    "            raise UpdateError('AppImage download SHA-256 or size mismatch.')\n"
    "        if not is_x64_appimage(staged):\n"
    "            raise UpdateError('Release asset is not a valid x86-64 AppImage header.')\n"
    "        staged.chmod(0o755)\n"
    "        # Back up to a separate path so recovery is possible if the new build fails.\n"
    "        backup = dest.with_name(dest.name + '.previous')\n"
    "        if backup.is_symlink() or (backup.exists() and not backup.is_file()):\n"
    "            raise UpdateError('AppImage backup path is not a regular file.')\n"
    "        fd_backup, temp_backup = tempfile.mkstemp(dir=dest.parent, prefix='.file-sorter-backup-')\n"
    "        try:\n"
    "            with os.fdopen(fd_backup, 'wb') as output, open(dest, 'rb') as original:\n"
    "                shutil.copyfileobj(original, output)\n"
    "                output.flush()\n"
    "                os.fsync(output.fileno())\n"
    "            os.chmod(temp_backup, dest.stat().st_mode & 0o777)\n"
    "            os.replace(temp_backup, backup)\n"
    "            os.replace(staged, dest)\n"
    "        finally:\n"
    "            if os.path.exists(temp_backup):\n"
    "                os.unlink(temp_backup)\n"
    "    finally:\n"
    "        staged.unlink(missing_ok=True)\n"
    "\n"
    "\n"
    "def run_appimage(args):\n"
    "    dest = Path(os.path.abspath(os.path.expanduser(args.appimage)))\n"
    "    if not dest.is_file() or dest.is_symlink():\n"
    "        raise UpdateError('AppImage path must refer to an existing regular file, not a symlink.')\n"
    "    cfg = config_dir()\n"
    "    cfg.mkdir(mode=0o700, parents=True, exist_ok=True)\n"
    "    with open(cfg / 'updater.lock', 'a+b') as lock:\n"
    "        try:\n"
    "            fcntl.flock(lock.fileno(), fcntl.LOCK_EX | fcntl.LOCK_NB)\n"
    "        except BlockingIOError:\n"
    "            if not args.quiet:\n"
    "                print('An update is already running.', flush=True)\n"
    "            return 0\n"
    "        if args.auto:\n"
    "            stamp = cfg / 'last-auto-check-appimage'\n"
    "            try:\n"
    "                if time.time() - float(stamp.read_text()) < 6 * 3600:\n"
    "                    return 0\n"
    "            except (OSError, ValueError):\n"
    "                pass\n"
    "        result = latest_appimage()\n"
    "        if not result:\n"
    "            if not args.quiet:\n"
    "                print('Latest release does not contain an AppImage yet.', flush=True)\n"
    "        else:\n"
    "            version, asset = result\n"
    "            # The script is embedded in the running AppImage. Its build version\n"
    "            # is the version of the running GUI even if the AppImage was renamed.\n"
    "            if version <= BUILD_VERSION:\n"
    "                if not args.quiet:\n"
    "                    print('Up to date: v' + '.'.join(map(str, BUILD_VERSION)), flush=True)\n"
    "            elif not args.install:\n"
    "                print('New AppImage available: ' + asset['name'], flush=True)\n"
    "            else:\n"
    "                print('Downloading verified AppImage: ' + asset['name'], flush=True)\n"
    "                install_appimage(dest, asset)\n"
    "                print('AppImage installed. Close all File Sorter windows and restart.', flush=True)\n"
    "        if args.auto:\n"
    "            (cfg / 'last-auto-check-appimage').write_text(str(time.time()), encoding='ascii')\n"
    "    return 0\n"
    "\n"
    "\n"
    "def main(argv=None):\n"
    "    parser = argparse.ArgumentParser(description='Update File Sorter from GitHub Releases')\n"
    "    parser.add_argument('--version', action='version', version='File Sorter Updater v1.3.9')\n"
    "    target = parser.add_mutually_exclusive_group(required=True)\n"
    "    target.add_argument('--app-dir', help='Directory of separate ELF programs')\n"
    "    target.add_argument('--appimage', help='Path to one installed File Sorter AppImage')\n"
    "    parser.add_argument('--current-tag', default=None, help='Legacy compatibility; version comes from ZIP filename')\n"
    "    parser.add_argument('--check', action='store_true')\n"
    "    parser.add_argument('--install', action='store_true')\n"
    "    parser.add_argument('--auto', action='store_true', help='Install automatically, at most once every 6 hours')\n"
    "    parser.add_argument('--quiet', action='store_true')\n"
    "    args = parser.parse_args(argv)\n"
    "    if not (args.check or args.install or args.auto):\n"
    "        parser.error('Choose --check, --install or --auto.')\n"
    "    if args.auto:\n"
    "        args.install = True\n"
    "        args.quiet = True\n"
    "    try:\n"
    "        return run_appimage(args) if args.appimage else run(args)\n"
    "    except (UpdateError, OSError, zipfile.BadZipFile) as exc:\n"
    "        print('Update failed: ' + str(exc), file=sys.stderr, flush=True)\n"
    "        return 1\n"
    "\n"
    "\n"
    "if __name__ == '__main__':\n"
    "    sys.exit(main())\n";
